trigger_evidence:
Alert.alert(
      "WMS Access Blocked",
      "My Workorders is only available to FWR and SPV(SUBC) users.",
      [
        {
          text: "OK",
          onPress: () => {
            if (router?.canGoBack?.()) {
              router.back();
            }
          },
        },
      ],
    )

message:
`Meter ${lookup.meterNo || "of this row"} could not be looked up. ${
              connectionFailed
                ? "Check your connection and try again."
                : "Try again; if it keeps failing, tell the office."
            }`

trigger_evidence:
Alert.alert(
            "Meter not looked up",
            `Meter ${lookup.meterNo || "of this row"} could not be looked up. ${
              connectionFailed
                ? "Check your connection and try again."
                : "Try again; if it keeps failing, tell the office."
            }`,
          )

Alert.alert(
          "Targeted Batch Accepted",
          result?.message ||
            "The Targeted Batch row worklist is now ready for field execution.",
          [
            {
              text: "LATER",
              style: "cancel",
            },
            {
              text: "VIEW TRANSACTIONS",
              onPress: () => {
                setPreparingBgoDetail(false);
                setSelectedBucket(acceptedBucket);
                setSelectedGroup(null);
                setStateFilter("ALL");
              },
            },
          ],
        )

Alert.alert("Accept Work", `Accept ${item?.id || "this work item"}?`, [
      { text: "CANCEL", style: "cancel" },
      {
        text: "ACCEPT",
        onPress: () => submitDecision({ item, action: "ACCEPT" }),
      },
    ])

Alert.alert(
      "Accept Targeted Batch",
      `Accept ${bucket?.id || "this Targeted Batch"}? Its rows will be opened for premise and meter discovery work.`,
      [
        { text: "CANCEL", style: "cancel" },
        {
          text: "ACCEPT",
          onPress: () =>
            submitTargetedBatchDecision({
              bucket,
              action: "ACCEPT",
            }),
        },
      ],
    )

Alert.alert(
      "Reverse BGO Acceptance",
      "This is online-only and will only work if no child TRN has started execution. Reverse this BGO bucket acceptance?",
      [
        { text: "CANCEL", style: "cancel" },
        {
          text: "REVERSE",
          style: "destructive",
          onPress: async () => {
            try {
              const result = await reverseBgoBatchAcceptance({
                batchId: bucket.id,
                reason: "Manager reversed BGO acceptance before execution started",
              }).unwrap();

              if (result?.success === false) {
                throw {
                  data: result,
                  message: result?.message || "Reverse acceptance failed.",
                };
              }

              Alert.alert(
                "BGO Acceptance Reversed",
                result?.message || "BGO bucket acceptance was reversed.",
              );

              safeRefetch(refetchBgo, "BGO buckets");
              safeRefetch(refetch, "individual work");
              safeRefetch(refetchBgoDetail, "BGO detail TRNs");
              backToBuckets();
            } catch (err) {
              console.log("BGO reverse acceptance ERROR", err);

              Alert.alert(
                "Reverse Failed",
                getActionErrorMessage(err, "Could not reverse BGO acceptance."),
              );
            }
          },
        },
      ],
    )

buildFailureResult(
          "UNAUTHORIZED_LCT_ASSIGNEE_ACTION",
          "Only field workers or supervisors can accept or reject assigned lifecycle instructions",
          {
            actorRole: actorRole || "UNKNOWN",
          },
        )

buildFailureResult(
          "TOO_MANY_TRNS",
          "A maximum of 50 TRNs can be accepted or rejected at once",
          {
            count: trnIds.length,
          },
        )

buildFailureResult(
            "TRN_NOT_FOUND",
            "One or more TRNs were not found",
            {
              missingTrnIds,
            },
          )

buildFailureResult(
              "TRN_ALREADY_COMPLETED",
              "Completed lifecycle instructions cannot be accepted or rejected",
              {
                trnId: row.trnId,
                trnType,
                workflowState: workflowState || "NAv",
              },
            )

buildFailureResult(
              "TRN_CANCELLED",
              "Cancelled TRNs cannot be accepted or rejected",
              {
                trnId: row.trnId,
                trnType,
                workflowState: workflowState || "NAv",
              },
            )

buildFailureResult(
              "INVALID_WORKFLOW_STATE",
              getInvalidWorkflowStateMessage(action),
              {
                trnId: row.trnId,
                trnType,
                workflowState: workflowState || "NAv",
                allowedWorkflowStates,
              },
            )

buildFailureResult(
              "TRN_NOT_ASSIGNED_TO_ACTOR",
              "This TRN is not assigned to the current field actor",
              {
                trnId: row.trnId,
                trnType,
                targets,
              },
            )

buildFailureResult(
              "INVALID_AST_ID",
              "TRN is missing ast.astData.astId",
              {
                trnId: row.trnId,
                trnType,
              },
            )

buildFailureResult(
              "AST_NOT_FOUND",
              "The referenced AST does not exist",
              {
                trnId: row.trnId,
                trnType,
                astId,
              },
            )
